(6,1,'2026-11-11 16:35:33','2026-11-11 16:35:33','<!-- wp:cover {\"url\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/adc6a64b-f5d8-4050-8b82-989eb6aedacc-1.webp\",\"id\":39,\"alt\":\"Wnętrze Kawiarni Ziarno\\u0026Kawa\",\"dimRatio\":70,\"overlayColor\":\"custom-tekst\",\"isUserOverlayColor\":true,\"focalPoint\":{\"x\":0.49,\"y\":0.47},\"minHeight\":100,\"minHeightUnit\":\"vh\",\"sizeSlug\":\"full\",\"metadata\":{\"patternName\":\"core/block/63\",\"name\":\"Wzorzec Hero Ziarno\\u0026kawa\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}}},\"fontSize\":\"x-large\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover alignfull has-x-large-font-size\" style=\"padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0;padding-left:var(--wp--preset--spacing--30);min-height:100vh\"><img class=\"wp-block-cover__image-background wp-image-39 size-full\" alt=\"Wnętrze Kawiarni Ziarno&amp;Kawa\" src=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/adc6a64b-f5d8-4050-8b82-989eb6aedacc-1.webp\" style=\"object-position:49% 47%\" data-object-fit=\"cover\" data-object-position=\"49% 47%\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-custom-tekst-background-color has-background-dim-70 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h1 class=\"wp-block-heading has-text-align-center\"><strong>Rzemieślnicza kawa wypalana z pasją</strong></h1>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Odkryj selekcję świeżo palonych ziaren specialty oraz weź udział w warsztatach baristycznych.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-right wp-element-button\" href=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/oferta/\">Zobacz ofertę</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Dlaczego Ziarno&amp;Kawa?</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"0\"}}},\"backgroundColor\":\"custom-t-o\"} -->\n<div class=\"wp-block-columns alignwide has-custom-t-o-background-color has-background\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/swieze-palenie-kawy-kolumna-1.webp\",\"id\":42,\"alt\":\"Świeżo palne ziarna kawy arabica\",\"dimRatio\":80,\"overlayColor\":\"custom-tekst\",\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\"><img class=\"wp-block-cover__image-background wp-image-42 size-full\" alt=\"Świeżo palne ziarna kawy arabica\" src=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/swieze-palenie-kawy-kolumna-1.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-custom-tekst-background-color has-background-dim-80 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\">Świeże palenie kawy</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"100%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:100%\"><!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Wypalamy rzemieślnicze ziarna na bieżąco w małych partiach, dbając o pełnię aromatu.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"backgroundColor\":\"custom-tekst\"} -->\n<div class=\"wp-block-column has-custom-tekst-background-color has-background\"><!-- wp:cover {\"url\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-2.webp\",\"id\":43,\"alt\":\"Barista powoli polewa gorącą wodą zmieloną kawę\",\"dimRatio\":80,\"overlayColor\":\"custom-tekst\",\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\"><img class=\"wp-block-cover__image-background wp-image-43 size-full\" alt=\"Barista powoli polewa gorącą wodą zmieloną kawę\" src=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-2.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-custom-tekst-background-color has-background-dim-80 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"level\":3,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-t-o\"}}},\"typography\":{\"textAlign\":\"center\"}},\"textColor\":\"custom-t-o\"} -->\n<h3 class=\"wp-block-heading has-text-align-center has-custom-t-o-color has-text-color has-link-color\">Metody przelewowe</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Parzymy w Dripperze V60, Chemexie i Aeropressie według autorskich receptur naszych baristów.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-3.webp\",\"id\":44,\"alt\":\"Grupa uczestników warsztatów i cuppingu w Kawiarni\",\"dimRatio\":80,\"overlayColor\":\"custom-tekst\",\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\"><img class=\"wp-block-cover__image-background wp-image-44 size-full\" alt=\"Grupa uczestników warsztatów i cuppingu w Kawiarni\" src=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-3.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-custom-tekst-background-color has-background-dim-80 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\">Warsztaty i cupping</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Uczymy prawidłowego parzenia w domu, degustacji sensorycznej oraz podstaw latte art</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:quote {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\"} -->\n<blockquote class=\"wp-block-quote has-contrast-color has-text-color has-link-color\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\"> <em>„Najlepsze espresso w mieście i świetne warsztaty baristyczne!”</em> <em>— Jan Kowalski</em></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">\"Smaczna kawa oraz przemiła obsługa\" - Marta</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Strona główna','','publish','closed','closed','','strona-glowna','','','2026-11-16 17:50:09','2026-11-16 17:50:09','',0,'https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/?page_id=6',0,'page','',0),
