g\":\"custom-kolor-marki\"},{\"color\":\"#8c4a27\",\"name\":\"Akcent\",\"slug\":\"custom-akcent\"}]}},\"typography\":{\"fontSizes\":{\"custom\":[{\"name\":\"New Font Size 1\",\"size\":\"16px\",\"slug\":\"custom-1\"}]},\"fontFamilies\":{\"theme\":[{\"name\":\"Manrope\",\"slug\":\"manrope\",\"fontFamily\":\"Manrope, sans-serif\",\"fontFace\":[{\"src\":[\"file:./assets/fonts/manrope/Manrope-VariableFont_wght.woff2\"],\"fontWeight\":\"200 800\",\"fontStyle\":\"normal\",\"fontFamily\":\"Manrope\"}]},{\"name\":\"Fira Code\",\"slug\":\"fira-code\",\"fontFamily\":\"\\\"Fira Code\\\", monospace\",\"fontFace\":[{\"src\":[\"file:./assets/fonts/fira-code/FiraCode-VariableFont_wght.woff2\"],\"fontWeight\":\"300 700\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"Fira Code\\\"\"}]}],\"custom\":[{\"name\":\"Lora\",\"slug\":\"lora\",\"fontFamily\":\"Lora\",\"preview\":\"\",\"fontFace\":[{\"fontFamily\":\"Lora\",\"fontStyle\":\"italic\",\"fontWeight\":\"400 700\",\"src\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/fonts/Lora-Italic-VariableFont_wght.ttf\"},{\"fontFamily\":\"Lora\",\"fontStyle\":\"normal\",\"fontWeight\":\"400 700\",\"src\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/fonts/Lora-VariableFont_wght.ttf\"}]}]}}},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}','Custom Styles','','publish','closed','closed','','wp-global-styles-twentytwentyfive','','','2026-11-17 18:04:28','2026-11-17 18:04:28','',0,'https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-global-styles-twentytwentyfive/',0,'wp_global_styles','',0),
