(11,1,'2026-11-11 16:36:53','2026-11-11 16:36:53','<!-- wp:cover {\"url\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/adc6a64b-f5d8-4050-8b82-989eb6aedacc-1.webp\",\"id\":39,\"alt\":\"Przytulne, rzemieślnicze wnętrze palarni kawy i kawiarni Ziarno\\u0026Kawa z drewnianym barem, piecem do wypalania ziaren i workami z surową kawą.\",\"dimRatio\":70,\"overlayColor\":\"custom-tekst\",\"isUserOverlayColor\":true,\"focalPoint\":{\"x\":0.54,\"y\":0.49},\"minHeight\":816,\"minHeightUnit\":\"px\",\"sizeSlug\":\"full\",\"metadata\":{\"categories\":[],\"name\":\"Wzorzec Hero Ziarno\\u0026kawa\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"var:preset|spacing|30\",\"right\":\"var:preset|spacing|30\"}}},\"fontSize\":\"x-large\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover alignfull has-x-large-font-size\" style=\"padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0;padding-left:var(--wp--preset--spacing--30);min-height:816px\"><img class=\"wp-block-cover__image-background wp-image-39 size-full\" alt=\"Przytulne, rzemieślnicze wnętrze palarni kawy i kawiarni Ziarno&amp;Kawa z drewnianym barem, piecem do wypalania ziaren i workami z surową kawą.\" src=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/adc6a64b-f5d8-4050-8b82-989eb6aedacc-1.webp\" style=\"object-position:54% 49%\" data-object-fit=\"cover\" data-object-position=\"54% 49%\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-custom-tekst-background-color has-background-dim-70 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":1,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Poznaj naszą ofertę</h1>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"align\":\"wide\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center alignwide\">W naszej palarni i kawiarni stawiamy na świeżo wypalane ziarna segmentu speciality oraz rzemieślnicze podejście do parzenia kawy. Wybierz interesujący Cię obszar, aby sprawdzić aktualne menu lokalu, zapisać się na warsztaty baristyczne lub zamówić ziarna do domu.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-right wp-element-button\" href=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/oferta/kawiarnia-i-menu-2/\">Kawiarnia i menu</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-right wp-element-button\" href=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/oferta/ziarna-na-wynos/\">Ziarna na wynos</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"style\":{\"typography\":{\"textAlign\":\"right\"}}} -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-text-align-right wp-element-button\" href=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/oferta/warsztaty/\">Warsztaty</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:cover -->','Oferta','','publish','closed','closed','','oferta','','','2026-11-17 18:42:49','2026-11-17 18:42:49','',0,'https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/?page_id=11',0,'page','',0),
