(15,1,'2026-11-11 16:37:40','2026-11-11 16:37:40','<!-- wp:heading {\"level\":1,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<h1 class=\"wp-block-heading has-custom-tekst-color has-text-color has-link-color\">Kontakt</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<h2 class=\"wp-block-heading has-custom-tekst-color has-text-color has-link-color\">Odwiedź naszą kawiarnię</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">ul. Kawowa 12, 62-030 Luboń</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">Godziny otwarcia:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">Pn - Pt   7:30 - 19:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Sobota 9:00 - 20:00</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">Telefon : 48-555-666-777</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">Email: <a hre