https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/swieze-palenie-kawy-kolumna-1.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-contrast-background-color has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Świeże palenie kawy</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"100%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:100%\"><!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Wypalamy rzemieślnicze ziarna na bieżąco w małych partiach, dbając o pełnię aromatu.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-2.webp\",\"id\":43,\"alt\":\"Barista powoli polewa gorącą wodą zmieloną kawę w ceramicznym dripperze V60 na drewnianym barze, z czarnego czajnika z gęsią szyjką\",\"dimRatio\":50,\"overlayColor\":\"contrast\",\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\"><img class=\"wp-block-cover__image-background wp-image-43 size-full\" alt=\"Barista powoli polewa gorącą wodą zmieloną kawę w ceramicznym dripperze V60 na drewnianym barze, z czarnego czajnika z gęsią szyjką\" src=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-2.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-contrast-background-color has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"level\":3,\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|base\"}}}},\"textColor\":\"base\"} -->\n<h3 class=\"wp-block-heading has-base-color has-text-color has-link-color\">Metody przelewowe</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Parzymy w Dripperze V60, Chemexie i Aeropressie według autorskich receptur naszych baristów.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-3.webp\",\"id\":44,\"alt\":\"Grupa uczestników warsztatów i cuppingu w palarni Ziarno\\u0026Kawa, stojąca wokół długiego stołu z miseczkami do degustacji i notatnikami, prowadzona przez baristę.\",\"dimRatio\":50,\"overlayColor\":\"contrast\",\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\"><img class=\"wp-block-cover__image-background wp-image-44 size-full\" alt=\"Grupa uczestników warsztatów i cuppingu w palarni Ziarno&amp;Kawa, stojąca wokół długiego stołu z miseczkami do degustacji i notatnikami, prowadzona przez baristę.\" src=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-3.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-contrast-background-color has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Warsztaty i cupping</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Uczymy prawidłowego parzenia w domu, degustacji sensorycznej oraz podstaw latte art</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:quote {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\"} -->\n<blockquote class=\"wp-block-quote has-contrast-color has-text-color has-link-color\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\"> <em>„Najlepsze espresso w mieście i świetne warsztaty baristyczne!”</em> <em>— Jan Kowalski</em></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">\"Smaczna kawa oraz przemiła obsługa\" - Marta</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Strona główna','','inherit','closed','closed','','6-revision-v1','','','2026-11-14 18:11:08','2026-11-14 18:11:08','',6,'https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/?p=90',0,'revision','',0),
