 wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Parzymy w Dripperze V60, Chemexie i Aeropressie według autorskich receptur naszych baristów.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:cover {\"url\":\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-3.webp\",\"id\":44,\"alt\":\"Grupa uczestników warsztatów i cuppingu w Kawiarni\",\"dimRatio\":80,\"overlayColor\":\"custom-tekst\",\"isUserOverlayColor\":true,\"sizeSlug\":\"full\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-cover\"><img class=\"wp-block-cover__image-background wp-image-44 size-full\" alt=\"Grupa uczestników warsztatów i cuppingu w Kawiarni\" src=\"https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/wp-content/uploads/2026/11/kolumna-3.webp\" data-object-fit=\"cover\"/><span aria-hidden=\"true\" class=\"wp-block-cover__background has-custom-tekst-background-color has-background-dim-80 has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h3 class=\"wp-block-heading has-text-align-center\">Warsztaty i cupping</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"placeholder\":\"Write title…\",\"style\":{\"typography\":{\"textAlign\":\"center\"}},\"fontSize\":\"large\"} -->\n<p class=\"has-text-align-center has-large-font-size\">Uczymy prawidłowego parzenia w domu, degustacji sensorycznej oraz podstaw latte art</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:quote {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast\"}}}},\"textColor\":\"contrast\"} -->\n<blockquote class=\"wp-block-quote has-contrast-color has-text-color has-link-color\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\"> <em>„Najlepsze espresso w mieście i świetne warsztaty baristyczne!”</em> <em>— Jan Kowalski</em></p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">\"Smaczna kawa oraz przemiła obsługa\" - Marta</p>\n<!-- /wp:paragraph --></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Strona główna','','inherit','closed','closed','','6-revision-v1','','','2026-11-15 12:08:46','2026-11-15 12:08:46','',6,'https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/?p=104',0,'revision','',0),
