(125,1,'2026-11-16 18:06:00','2026-11-16 18:06:00','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Kawiarnia i Menu</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-tekst\"}}}},\"textColor\":\"custom-tekst\"} -->\n<p class=\"has-custom-tekst-color has-text-color has-link-color\">Zapraszamy do naszej kawiarni przy rzemieślniczej palarni <strong>Ziarno &amp; Kawa</strong>, gdzie każdego dnia parzymy świeżo wypalone ziarna jakości specialty. Niezależnie od tego, czy szukasz klasycznego, gęstego espresso, czy owocowego przelewu z dripa — nasi bariści przygotują kawę dopasowaną do Twoich preferencji.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:table -->\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><td><strong>Pozycja</strong></td><td><strong>Opis</strong></td><td><strong>Pojemność</strong></td><td><strong>Cena</strong></td></tr></thead><tbody><tr><td><strong>Espresso / Doppio</strong></td><td>Klasyczny napar na bazie naszej autorskiej mieszanki Brazylia &amp; Kolumbia o nutach czekolady i prażonych orzechów.</td><td>30 ml / 60 ml</td><td>11 zł / 13 zł</td></tr><tr><td><strong>Flat White</strong></td><td>Podwójne espresso z aksamitnie spienionym mlekiem (dostępne również napoje roślinne: owsiane, grochowe).</td><td>200 ml</td><td>16 zł</td></tr><tr><td><strong>Cappuccino</strong></td><td>Zbalansowane połączenie pojedynczego espresso i puszystej mlecznej pianki.</td><td>220 ml</td><td>15 zł</td></tr><tr><td><strong>Przelew (V60 / Chemex / AeroPress)</strong></td><td>Alternatywne metody parzenia wydobywające kwiatowe i owocowe nuty z ziaren single origin (Etiopia, Kenia, Rwanda).</td><td>250 ml / 400 ml</td><td>18 zł / 26 zł</td></tr><tr><td><strong>Batch Brew (Kawa przelewowa)</strong></td><td>Świeżo parzona kawa z ekspresu przelewowego — szybka, aromatyczna i gotowa od ręki.</td><td>250 ml</td><td>13 zł</td></tr><tr><td><strong>Cold Brew</strong></td><td>Kawa macerowana na zimno przez 16 godzin, podawana na kostkach lodu z plastrem pomarańczy.</td><td>300 ml</td><td>17 zł</td></tr></tbody></table></figure>\n<!-- /wp:table --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Domowe wypieki i dodatki</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Sernik baskijski z wanilią</strong> — kremowy, lekko karmelizowany na wierzchu <em>(18 zł)</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Cynamonka z kardamonem</strong> — wypiekana codziennie rano na naturalnym maśle <em>(14 zł)</em></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Tarta czekoladowa z solą morską</strong> — na bazie gorzkiej czekolady 70% <em>(17 zł)</em></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Godziny otwarcia i lokalizacja</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><strong>Poniedziałek – Piątek:</strong> 07:30 – 19:00</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Sobota :</strong> 09:30 – 20:00</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Adres:</strong> ul. Kawowa 12, Poznań (możliwość zakupu świeżo palonych ziaren na miejscu z bezpłatnym mieleniem pod wybraną metodę parzenia)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Kawiarnia i menu','','publish','closed','closed','','kawiarnia-i-menu-2','','','2026-11-16 18:18:59','2026-11-16 18:18:59','',11,'https://turbo-carnival-x5776v6qj46j2prw7-8080.app.github.dev/?page_id=125',0,'page','',0),
