ontStyle\":\"italic\",\"fontWeight\":\"400\"}}},\"color\":{\"text\":\"var(--wp--preset--color--custom-tekst)\",\"background\":\"var(--wp--preset--color--custom-t-o)\"},\"typography\":{\"lineHeight\":\"1.4\",\"fontSize\":\"1.13rem\"},\"css\":\"/* Dodatkowy CSS (Additional CSS) - dost\\u0119pno\\u015b\\u0107 i responsywno\\u015b\\u0107 */\\n\\n/* WCAG 2.4.7: widoczny fokus - nigdy samo outline: none */\\n:where(a, button, input, select, textarea, summary):focus-visible {\\n  outline: 3px solid var(--wp--preset--color--contrast, #1E1A17);\\n  outline-offset: 3px;\\n}\\n\\n/* WCAG 2.4.11: element z fokusem nie mo\\u017ce chowa\\u0107 si\\u0119 pod przyklejonym nag\\u0142\\u00f3wkiem */\\nhtml {\\n  scroll-padding-top: 5rem;\\n}\\n\\n/* WCAG 2.5.8: cel dotykowy min. 24 x 24 px */\\n.wp-block-navigation-item__content,\\n.wp-block-social-link a {\\n  min-height: 24px;\\n  min-width: 24px;\\n  padding-block: 0.5rem;\\n}\\n\\n/* P\\u0142ynna typografia zamiast wielu breakpoint\\u00f3w */\\nh1 {\\n  font-size: clamp(1.75rem, 1.2rem + 2.5vw, 3rem);\\n}\\n\\n/* Mobile first: kolumny jedna pod drug\\u0105 z odst\\u0119pami na w\\u0105skich ekranach */\\n@media (max-width: 600px) {\\n  .wp-block-columns {\\n    gap: 1.25rem;\\n  }\\n  .wp-block-columns .wp-block-column {\\n    margin-bottom: 1.25rem;\\n  }\\n  .wp-block-cover {\\n    min-height: 45vh;\\n    padding-inline: 1rem;\\n  }\\n}\\n/* WCAG 1.4.3: ciemny kolor bazowy pod zdj\\u0119ciem Cover dla bia\\u0142ego tekstu */\\n.wp-block-cover {\\n  background-color: #1E1A17 !important;\\n}\\n/* Ukrycie pola-pu\\u0142apki (honeypot) z widoku wizualnego */\\n.hp-field {\\n  position: absolute;\\n  left: -9999px;\\n  width: 1px;\\n  height: 1px;\\n  overflow: hidden;\\n}\\n\\n/* WCAG 2.5.8 Target Size (min. 24x24 px) dla checkboxa RODO i przycisku */\\n.wpcf7-form input[type=\\\"checkbox\\\"] {\\n  width: 24px;\\n  height: 24px;\\n  min-width: 24px;\\n  min-height: 24px;\\n  vertical-align: middle;\\n  margin-right: 8px;\\n  cursor: pointer;\\n}\\n\\n.wpcf7-form input[type=\\\"submit\\\"] {\\n  min-width: 44px;\\n  min-height: 44px;\\n  padding: 12px 24px;\\n  cursor: pointer;\\n}\\n\\n/* Wyra\\u017any fokus dla nawigacji klawiatur\\u0105 */\\n.wpcf7-form input:focus-visible,\\n.wpcf7-form textarea:focus-visible {\\n  outline: 3px solid #2b2118;\\n  outline-offset: 2px;\\n}\"},\"settings\":{\"color\":{\"palette\":{\"theme\":[{\"color\":\"#DFDCD7\",\"name\":\"Base\",\"slug\":\"base\"},{\"color\":\"#191919\",\"name\":\"Contrast\",\"slug\":\"contrast\"},{\"color\":\"#7A9BDB\",\"name\":\"Accent 1\",\"slug\":\"accent-1\"},{\"color\":\"#F7E6FF\",\"name\":\"Accent 2\",\"slug\":\"accent-2\"},{\"color\":\"#182949\",\"name\":\"Accent 3\",\"slug\":\"accent-3\"},{\"color\":\"#5F5F5F\",\"name\":\"Accent 4\",\"slug\":\"accent-4\"},{\"color\":\"#D7D3CC\",\"name\":\"Accent 5\",\"slug\":\"accent-5\"},{\"color\":\"#19191933\",\"name\":\"Accent 6\",\"slug\":\"accent-6\"}],\"custom\":[{\"color\":\"#faf7f2\",\"name\":\"T\\u0142o\",\"slug\":\"custom-t-o\"},{\"color\":\"#1e1a17\",\"name\":\"Tekst\",\"slug\":\"custom-tekst\"},{\"color\":\"#5c3a21\",\"name\":\"Kolor Marki\",\"slug\":\"custom-kolor-marki\"},{\"color\":\"#8c4a27\",\"name\":\"Akcent\",\"slug\":\"custom-akcent\"}]}},\"typography\":{\"fontSizes\":{\"custom\":[{\"name\":\"New Font Size 1\",\"size\":\"16px\",\"slug\":\"custom-1\"}]},\"fontFamilies\":{\"theme\":[{\"name\":\"Manrope\",\"slug\":\"manrope\",\"fontFamily\":\"Manrope, sans-serif\",\"fontFace\":[{\"src\":[\"file:./assets/fonts/manrope/Manrope-VariableFont_wght.woff2\"],\"fontWeight\":\"200 800\",\"fontStyle\":\"normal\",\"fontFamily\":\"Manrope\"}]},{\"name\":\"Fira Code\",\"slug\":\"fira-code\",\"fontFamily\":\"\\\"Fira Code\\\", monospace\",\"fontFace\":[{\"src\":[\"file:./assets/fonts/fira-code/FiraCode-VariableFont_wght.woff2\"],\"fontWeight\":\"300 700\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"Fira Code\\\"\"}]}],\"custom\":[{\"name\":\"Lora\",\"slug\":\"lora\",\"fontFamily\":\"Lora\",